const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icons={campaign:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 10h18M8 3v4M16 3v4"/>',template:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M10 3v18M10 11h11"/>',assets:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',review:'<path d="M8 4H5v17h14V4h-3M9 3h6v4H9zM8 14l3 3 5-6"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[k]||icons.campaign}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const langs=['한국어','English','Tiếng Việt','中文','日本語','ไทย','Bahasa Indonesia','Монгол','नेपाली','ខ្មែរ','မြန်မာ','O‘zbek'];
const codes=['ko','en','vi','zh','ja','th','id','mn','ne','km','my','uz'];
const sizes=[{name:'팝업 배너',w:800,h:840,example:true,cls:''},{name:'메인 배너',w:1200,h:500,example:true,cls:'landscape'},{name:'푸시 이미지',w:900,h:600,example:true,cls:'wide'},{name:'콘텐츠 이미지',w:1200,h:1200,example:false,cls:'content'}];
const defaults={title:'버스 타고,\n할인도 타고!',short:'버스 할인 쿠폰',desc:'한패스로 예매하고 더 가볍게 떠나요',amount:'5,000',coupon:'DEMO-BUS5000',period:'2026.09.15 – 2026.09.30',note:'본 쿠폰은 프로토타입용 데모입니다. 실제 사용 불가.'};
let campaigns=[{name:'버스 할인 쿠폰 이벤트',owner:'김민지',date:'2026-09-15',status:'작업 중',langs:12,sizes:4,data:{...defaults}},{name:'신규가입 캐시백 이벤트',owner:'이서준',date:'2026-09-18',status:'검수 대기',langs:6,sizes:3,data:{...defaults,title:'첫 시작을 응원해요',short:'신규가입 캐시백',amount:'10,000'}},{name:'서비스 점검 공지',owner:'김민지',date:'2026-09-20',status:'승인 완료',langs:12,sizes:2,data:{...defaults,title:'더 나은 서비스를 위한\n정기 점검 안내',desc:'점검 시간 동안 서비스 이용이 잠시 중단됩니다.',amount:''}},{name:'교육생 모집 캠페인',owner:'박지우',date:'2026-09-25',status:'수정 필요',langs:4,sizes:2,data:{...defaults,title:'새로운 내일을\n함께 배워요',desc:'2026 하반기 교육생 모집',amount:''}}];
let state={page:'edit',campaign:0,lang:0,size:0,scope:'common',role:'요청자',zoom:100,safe:false,hide:false,version:3,save:'모든 변경사항 저장됨',overrides:{},translations:{},approved:{},requested:false,filter:'',owner:'전체 담당자',status:'전체 상태',problems:false,unreviewed:false,view:'matrix',color:'#dcedff',font:31,focus:50,asset:null,selection:[],history:[],download:'idle',format:'PNG',output:'approved',quality:90,bg:'#ffffff',newLangs:langs.map((_,i)=>i),newSizes:[0,1,2,3],template:0,searchAsset:'',assetCategory:'전체',brand:'Hanpass',settingsTab:'규격',newName:'',reviewed:{0:true,1:true,3:true,4:true},human:{},layout:'기본'};
const camp=()=>campaigns[state.campaign];const key=()=>`${state.lang}-${state.size}`;const data=()=>({...camp().data,...(state.overrides[key()]||{})});
const badge=s=>`<span class="badge ${s.includes('승인')?'ok':s.includes('넘침')||s.includes('수정')?'error':s.includes('검수')||s.includes('확인')?'warn':'blue'}">${s.includes('승인')?'✓':s.includes('넘침')||s.includes('수정')?'!':s.includes('검수')||s.includes('확인')?'◷':'•'} ${s}</span>`;
function status(l,s){if(state.approved[`${l}-${s}`]===state.version)return '승인 완료';if(l===2&&s===1&&!state.translations[2]?.short&&!state.overrides['2-1']?.short)return '글자 넘침';if(l===5&&s===0&&!state.overrides['5-0']?.imageChecked)return '이미지 확인 필요';if(!state.reviewed[l])return '번역 미검수';return state.requested?'검수 대기':'제작 완료'}
for(let l of [0,1,3,4])for(let s=0;s<4;s++)state.approved[`${l}-${s}`]=3;
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500)}
function navigate(p){state.page=p;location.hash=p;render();window.scrollTo(0,0)}
function confirmBox(title,body,action,label='확인'){const d=$('#dialog');d.innerHTML=`<h2>${title}</h2><p>${body}</p><div class="row" style="justify-content:flex-end"><button id="cancel">취소</button><button class="primary" id="confirm">${label}</button></div>`;d.showModal();$('#cancel').onclick=()=>d.close();$('#confirm').onclick=()=>{d.close();action()}}
function shell(content){const inCamp=['edit','languages','results','download'].includes(state.page);return `<aside class="sidebar"><div class="brand">hanpass<span>CREATIVE STUDIO</span></div><div class="workspace">WORKSPACE</div>${[['campaign','캠페인','campaigns'],['template','템플릿','templates'],['assets','에셋 라이브러리','assets'],['review','검수함','inbox'],['settings','브랜드·규격 설정','settings']].map(([i,n,p])=>`<button class="nav ${(state.page===p||(inCamp&&p==='campaigns')||state.page==='new'&&p==='campaigns')?'active':''}" data-nav="${p}">${icon(i)}<span>${n}</span>${p==='inbox'?'<span class="count">3</span>':''}</button>`).join('')}<div class="sidebottom"><div class="demo"><b>UI 프로토타입 · DEMO</b>번역, 승인, 파일 생성은<br>실제 서비스와 연결되지 않아요.</div><div class="person"><div class="avatar">민</div><div><b style="font-size:12px">김민지</b><small style="display:block">마케팅팀</small></div></div></div></aside><main class="main"><header class="topbar"><span>워크스페이스 <span style="padding:0 12px;color:#bcc2cc">/</span> ${inCamp?'캠페인 <span style="padding:0 12px">/</span> '+esc(camp().name):({campaigns:'캠페인',new:'새 캠페인',templates:'템플릿',assets:'에셋 라이브러리',inbox:'검수함',settings:'브랜드·규격 설정',request:'새 디자인 요청'}[state.page]||'캠페인')}</span><div class="row"><span class="rolelabel">데모 역할</span><select class="role" id="role">${['요청자','디자이너','언어 검수자','최종 승인자'].map(v=>`<option ${state.role===v?'selected':''}>${v}</option>`).join('')}</select><span class="avatar" style="width:28px;height:28px;font-size:11px">민</span></div></header>${inCamp?`<div class="pagehead"><div class="row between"><div><div class="row"><h1>${esc(camp().name)}</h1>${badge(camp().status)}</div><div class="sub"><span>김민지 · 마케팅팀</span><span>마감 ${camp().date.replaceAll('-','. ')}</span><span>템플릿 v2.1</span><span id="save" class="${state.save.includes('실패')?'saveerror':''}">✓ ${state.save}</span></div></div><button class="primary" id="requestReview">검수 요청 <span style="margin-left:12px">↗</span></button></div><div class="tabs">${[['edit','내용 편집',''],['languages','다국어',activeLangs().length],['results','전체 결과물',totalResults()],['download','검수·다운로드','']].map(([p,n,c])=>`<button data-nav="${p}" class="${state.page===p?'active':''}">${n}${c?`<span class="pill">${c}</span>`:''}</button>`).join('')}</div></div>`:''}${content}</main>`}
function banner(){const d=data();const tr=state.translations[state.lang];const title=(state.size===1&&(state.overrides[key()]?.short||tr?.short))||state.overrides[key()]?.title||(state.lang===0?d.title:tr?.title||(state.lang===1?'Your next ride,\na little lighter.':state.lang===2?'Ưu đãi giảm giá vé xe buýt dành riêng cho bạn':d.title));return `<div class="banner ${sizes[state.size].cls}" style="background:${state.color};aspect-ratio:${sizes[state.size].w}/${sizes[state.size].h};transform:scale(${state.zoom/100})"><div class="bannerbrand">${state.brand==='Hanpass'?'hanpass':'Go<i>Hanpass</i>'}<span style="float:right;font-size:7px;letter-spacing:1px">DEMO CAMPAIGN</span></div><div class="copy"><div class="eyebrow">HANPASS BUS PROMOTION</div><div class="btitle" style="${!sizes[state.size].cls?'font-size:'+state.font+'px':''}">${esc(title)}</div><div class="bdesc">${esc(state.overrides[key()]?.desc||tr?.desc||(state.lang===1?'Book your journey with Hanpass.':d.desc))}</div></div>${d.amount?`<div class="ticket"><small style="font-size:9px;color:#6b85a4">${state.lang===1?'YOUR RIDE DISCOUNT':'버스 예매 할인 쿠폰'}</small><div class="amount">${esc(d.amount)}<em>${state.lang===1?'KRW':'원'}</em></div><div class="coupon"><span>COUPON CODE</span><b>${esc(d.coupon)}</b></div></div>`:''}${state.asset?`<img alt="선택한 캠페인 이미지" src="${state.asset}" style="height:80px;width:100%;object-fit:cover;object-position:${state.focus}% center;margin-top:8px">`:''}<div class="bfoot">${esc(d.period)}<br>${esc(state.translations[state.lang]?.note||d.note)}</div>${state.safe?'<div class="safe"></div>':''}</div>`}
const field=(name,label,type='text')=>`<label class="field">${label}<${type==='textarea'?'textarea':'input'} data-field="${name}" ${type==='textarea'?'':`value="${esc(data()[name])}"`}>${type==='textarea'?esc(data()[name])+'</textarea>':''}</label>`;
function edit(){return `<div class="toolbar"><div class="row"><div class="seg"><button class="active" id="simple">간편 편집</button><button id="designer">${state.role!=='디자이너'?'🔒 ':''}디자이너 편집</button></div><span style="height:20px;border-left:1px solid var(--line)"></span><select id="lang" aria-label="현재 언어">${langs.map((l,i)=>activeLangs().includes(i)?`<option value="${i}" ${state.lang===i?'selected':''}>${l}${i===0?' · 원문':''}</option>`:'').join('')}</select><select id="size" aria-label="현재 규격">${sizes.map((s,i)=>activeSizes().includes(i)?`<option value="${i}" ${state.size===i?'selected':''}>${s.name} · ${s.w} × ${s.h}</option>`:'').join('')}</select></div><button class="ghost small" id="toggleChecks">☷ 검사 패널</button></div><div class="editor ${state.hide?'hidechecks':''}"><section class="panel"><div class="row between" style="margin-bottom:18px"><h3 style="margin:0">내용 입력</h3><span class="lockpill">승인 템플릿</span></div><div class="scope"><select id="scope" aria-label="변경 범위"><option value="common" ${state.scope==='common'?'selected':''}>⊕ 공통 내용 변경 · ${totalResults()}개 결과물</option><option value="local" ${state.scope==='local'?'selected':''}>현재 언어·규격만 변경</option></select><div>${state.scope==='common'?'금액·기간은 모든 언어에 공통 적용돼요.':'이 결과물에만 적용되는 개별 수정이에요.'}</div>${state.scope==='local'?'<button class="returnlink" id="resetOverride">공통 내용으로 되돌리기</button>':''}</div>${field('title','제목','textarea')}${field('short','짧은 제목')}${field('desc','설명','textarea')}${data().amount?field('amount','혜택 금액 (원)')+field('coupon','쿠폰번호 · 데모'):''}${field('period','행사 기간 · 데모')}${field('note','유의사항','textarea')}<label class="field">캠페인 이미지<button id="replaceAsset" style="width:100%;margin-top:7px">＋ 에셋에서 교체</button></label><button class="small ghost" id="saveFail">저장 실패 상태 체험</button></section><section class="canvasarea"><div class="canvasmeta"><span>${sizes[state.size].name.toUpperCase()} <span style="padding:0 6px">/</span> ${sizes[state.size].w} × ${sizes[state.size].h} px</span><span>${sizes[state.size].example?'예시 규격':'등록 규격'} · v${state.version}</span></div><div class="canvas" id="canvas">${banner()}</div><div class="row"><div class="zoom"><button id="zoomOut" aria-label="축소">−</button><span>${state.zoom}%</span><button id="zoomIn" aria-label="확대">＋</button><span style="color:#d8dce4">|</span><button id="fit">화면 맞춤</button></div><button class="small ${state.safe?'active':''}" id="safe">▣ 안전 영역</button></div><div class="thumbnails"><div class="row between"><span style="font-size:12px;color:#7d8797">현재 언어의 규격 <b style="color:#4f5d72;margin-left:5px">${activeSizes().length}</b></span><button class="ghost small" data-nav="results" style="color:#5274a8">전체 결과물 보기 ↗</button></div><div class="thumbgrid">${sizes.map((s,i)=>activeSizes().includes(i)?`<button class="thumb ${state.size===i?'active':''}" data-size="${i}"><span class="mini">버스 타고, 할인도 타고!<b>${esc(data().amount||'안내')}</b></span><span class="name">${s.name}</span><small>${s.w} × ${s.h} ${s.example?'· 예시':''}</small></button>`:'').join('')}</div></div><div class="footnote">규격별 승인 레이아웃이 적용돼요. 배너를 늘리거나 자르지 않아요.</div></section><section class="panel right"><h3>디자인 검사 <span class="badge blue" style="float:right">자동 검사 · 데모</span></h3><div class="checks"><div class="check"><b style="color:#2b9475">✓</b><div><strong>안전 영역 안에 배치됨</strong><span>등록된 안전 여백 40px</span></div></div><div class="check"><b style="color:${status(state.lang,state.size)==='글자 넘침'?'#d65b47':'#2b9475'}">${status(state.lang,state.size)==='글자 넘침'?'!':'✓'}</b><div><strong>${status(state.lang,state.size)==='글자 넘침'?'글자 넘침 · 수정 필요':'텍스트 길이 적절함'}</strong><span>최소 24px 이하로 줄이지 않아요</span></div></div><div class="check"><b style="color:#2b9475">✓</b><div><strong>브랜드 스타일 적용됨</strong><span>Hanpass · 템플릿 v2.1</span></div></div></div><div class="sectionline"></div><h3>선택 요소 <span class="badge" style="float:right">제목</span></h3><label class="field" style="font-size:12px">글자 크기 <span style="float:right;font-weight:400">${state.font}px</span><input id="font" type="range" min="24" max="36" value="${state.font}"><span class="hint">허용 범위 24–36px</span></label><label class="field" style="font-size:12px">승인된 배경 색상</label><div class="row">${['#dcedff','#e5f1ed','#fff0d7'].map(c=>`<button class="swatch" data-color="${c}" aria-label="배경색 ${c}" style="background:${c};${c===state.color?'outline:2px solid #2864ee':''}"></button>`).join('')}</div><div class="sectionline"></div><h3>이미지 초점</h3><input id="focus" type="range" min="0" max="100" value="${state.focus}" aria-label="이미지 초점 위치"><div class="row between muted" style="font-size:11px"><span>왼쪽</span><span>가운데</span><span>오른쪽</span></div><div class="sectionline"></div><h3>템플릿 보호 영역</h3>${['로고 비율','필수 안내 영역','기본 브랜드 스타일'].map(x=>`<div class="locked"><span>${x}</span><span>🔒 잠김</span></div>`).join('')}<div class="callout" style="font-size:11px;margin-top:20px">레이아웃 수정이 필요하면<br>디자이너에게 요청해 주세요.</div><div id="designerControls"></div></section></div>`}
function list(){let rows=campaigns.filter(c=>c.name.includes(state.filter)&&(state.owner==='전체 담당자'||c.owner===state.owner)&&(state.status==='전체 상태'||c.status===state.status));return `<div class="contentwrap"><div class="pagetitle"><div><h1>캠페인</h1><p>하나의 캠페인에서 모든 언어와 규격을 함께 관리해요.</p></div><button class="primary" data-nav="new">＋ 새 캠페인 만들기</button></div><div class="filters"><input id="search" placeholder="⌕ 캠페인명 검색" value="${esc(state.filter)}" aria-label="캠페인 검색"><select id="statusFilter">${['전체 상태','작업 중','검수 대기','수정 필요','승인 완료'].map(s=>`<option ${state.status===s?'selected':''}>${s}</option>`).join('')}</select><select id="ownerFilter">${['전체 담당자','김민지','이서준','박지우'].map(s=>`<option ${state.owner===s?'selected':''}>${s}</option>`).join('')}</select><span class="grow"></span><small>${rows.length}개 캠페인</small></div><div class="tablewrap"><table><thead><tr>${['캠페인명','담당자','마감일','언어·규격','작업 상태',''].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(c=>`<tr class="click"><td class="titlecell" tabindex="0" role="button" data-campaign="${campaigns.indexOf(c)}">${esc(c.name)}<small>Hanpass · 수정된 지 12분</small></td><td>${c.owner}</td><td>${c.date}</td><td>${c.langs}개 언어 · ${c.sizes}개 규격</td><td>${badge(c.status)}</td><td><button class="small" data-duplicate="${campaigns.indexOf(c)}">복제</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty"><h2>해당하는 캠페인이 없어요</h2><p>검색어나 필터를 바꿔 주세요.</p><button id="clearFilters" style="margin-top:16px">필터 초기화</button></div>':''}</div><p class="footnote">목록의 캠페인명을 선택해 이어서 작업하세요. 모든 캠페인 정보는 데모 데이터예요.</p></div>`}
const tnames=['버스 할인 쿠폰','신규가입 캐시백','서비스 점검 안내','교육생 모집','상품 소개'];
function templateCards(){return `<div class="templates">${tnames.map((n,i)=>`<button class="template ${state.template===i?'active':''}" data-template="${i}"><div class="art"><small>hanpass</small><b>${['버스 타고,<br>할인도 타고!','첫 시작에<br>10,000원 캐시백','더 나은 서비스를 위한<br>정기 점검 안내','새로운 내일을<br>함께 배워요','당신의 일상을 위한<br>한패스 서비스'][i]}</b><small>${['5,000원 할인 쿠폰','신규가입 고객 혜택','2026.09 · DEMO','2026 하반기 모집','HANPASS'][i]}</small></div><h3>${n} ${state.template===i?'✓':''}</h3><small>${['쿠폰·할인','캐시백·프로모션','서비스 공지','교육·모집 콘텐츠','상품 소개'][i]} · v2.1</small><small>팝업 · 메인 · 푸시 · 1200×1200</small>${state.page==='templates'?'<span class="badge ok" style="margin-top:8px">✓ 사용 가능</span>':''}</button>`).join('')}</div>`}
function creation(){return `<div class="contentwrap"><div class="progressrail"><b>01 캠페인 설정</b><span>—</span><span>02 내용 편집</span><span>—</span><span>03 검수·다운로드</span></div><div class="pagetitle"><div><h1>새 캠페인 만들기</h1><p>승인된 템플릿으로 제작을 시작하세요.</p></div><button data-nav="campaigns">취소</button></div><div class="card sectionspace"><div class="grid2"><label class="field">캠페인명 *<input id="newName" value="${esc(state.newName)}" placeholder="예: 9월 버스 할인 쿠폰 이벤트"></label><div class="split"><label class="field">담당자<select id="newOwner"><option>김민지</option><option>이서준</option><option>박지우</option></select></label><label class="field">마감일 *<input type="date" id="newDate" value="2026-09-30"></label></div></div><div class="row between" style="margin:15px 0"><h2>템플릿 선택</h2><button class="small" data-nav="request">원하는 디자인이 없나요? 새 디자인 요청 ↗</button></div>${templateCards()}</div><div class="grid2 sectionspace"><div class="card"><h2>사용 언어 <span class="badge">샘플 언어</span></h2><div class="chips">${langs.map((l,i)=>`<label><input type="checkbox" data-newlang="${i}" ${state.newLangs.includes(i)?'checked':''}> ${l}</label>`).join('')}</div><small>운영 언어 목록은 브랜드·규격 설정에서 변경할 수 있어요.</small></div><div class="card"><h2>출력 용도·규격</h2><div class="chips">${sizes.map((s,i)=>`<label><input type="checkbox" data-newsize="${i}" ${state.newSizes.includes(i)?'checked':''}> ${s.name}<br><small>${s.w} × ${s.h} ${s.example?'· 예시 규격':''}</small></label>`).join('')}</div><small>용도와 가로·세로 크기는 별도로 관리해요.</small></div></div><div class="summarybar"><div><span id="estimate"><b>${state.newLangs.length}개 언어 × ${state.newSizes.length}개 규격</b> <span style="padding:0 15px">=</span> <span class="countbig">${state.newLangs.length*state.newSizes.length}</span>개 결과물</span></div><button class="primary" id="create">캠페인 만들고 편집하기 →</button></div></div>`}
function languages(){let l=state.lang;return `<div class="contentwrap"><div class="row between" style="margin-bottom:20px"><div><h2>원문과 번역을 나란히 확인하세요</h2><small>${activeLangs().length}개 샘플 언어 · 자동 번역은 데모 초안이에요.</small></div><button id="autoTranslate">✧ 번역 초안 다시 만들기</button></div><div class="languagework"><div class="card languagelist" style="padding:9px">${langs.map((n,i)=>activeLangs().includes(i)?`<button data-lang="${i}" class="${i===l?'active':''}">${n}<small>${state.reviewed[i]?'✓ 검수 완료':'◷ 검수 필요'}</small></button>`:'').join('')}</div><div class="card"><div class="translatehead"><h2>한국어 원문 <span style="margin:0 25px;color:#a2abba">→</span> ${langs[l]}</h2>${badge(state.reviewed[l]?'승인 완료':'검수 필요')}</div><div class="callout">🔒 공통 데이터 보호 <b>${esc(camp().data.amount)}원</b> · ${esc(camp().data.coupon)} · ${esc(camp().data.period)}</div>${[['title','제목'],['desc','설명'],['short','짧은 문구'],['note','유의사항']].map(([k,n])=>`<div class="translatefield"><div><label>${n} · 원문</label><div class="source">${esc(camp().data[k])}</div></div><div><label>${n} · ${state.human[l]?'사람이 수정함':'자동 번역 초안 (데모)'}</label><textarea data-translate="${k}">${esc(state.translations[l]?.[k]||sampleTranslation(l,k))}</textarea>${l===2&&k==='title'?'<div class="errornote">! 메인 배너에서 글자 넘침 · 짧은 문구를 입력해 주세요.</div>':''}</div></div>`).join('')}<div class="row between"><small>금액·쿠폰번호·기간은 번역 대상에서 제외돼요.</small><button class="primary" id="approveLanguage">번역 검수 완료</button></div></div></div></div>`}
function sampleTranslation(l,k){if(l===0)return camp().data[k];if(l===1)return {title:'Your next ride, a little lighter.',desc:'Book your journey with Hanpass.',short:'Save on your next bus ride',note:'Demo coupon. Not valid for actual use.'}[k];if(l===2)return {title:'Ưu đãi giảm giá vé xe buýt dành riêng cho bạn',desc:'Đặt vé xe buýt với Hanpass',short:'',note:'Phiếu giảm giá mẫu. Không có giá trị sử dụng.'}[k];return `[${langs[l]} 데모 초안] ${camp().data[k]}`}
function results(){let ls=activeLangs().filter(l=>!state.unreviewed||!state.reviewed[l]);return `<div class="contentwrap"><div class="row between"><div><h2>${totalResults()}개 결과물, 한눈에 확인하기</h2><small>문제가 있는 결과물을 선택하면 해당 언어·규격의 편집기로 이동해요.</small></div><div class="seg"><button id="matrixView" class="${state.view==='matrix'?'active':''}">▦ 상태표</button><button id="thumbView" class="${state.view==='thumb'?'active':''}">▤ 썸네일</button></div></div><div class="filters"><label class="checkfilter"><input type="checkbox" id="problemFilter" ${state.problems?'checked':''}> 문제 있는 결과물만 보기</label><label class="checkfilter"><input type="checkbox" id="unreviewedFilter" ${state.unreviewed?'checked':''}> 미검수 언어만 보기</label><span class="grow"></span><small>✓ 승인 ${Object.values(state.approved).filter(v=>v===state.version).length} / ${totalResults()}</small></div>${state.view==='matrix'?`<div class="tablewrap"><table class="matrix"><thead><tr><th>언어 <small>샘플</small></th>${activeSizes().map(i=>sizes[i]).map(s=>`<th>${s.name}<br><small>${s.w}×${s.h} ${s.example?'· 예시':''}</small></th>`).join('')}</tr></thead><tbody>${ls.filter(l=>!state.problems||activeSizes().some(s=>/넘침|확인|미검수/.test(status(l,s)))).map(l=>`<tr><td><b>${langs[l]}</b><small style="margin-left:7px">${codes[l].toUpperCase()}</small></td>${activeSizes().map(i=>`<td><button data-result="${l}-${i}">${badge(status(l,i))}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="resultgrid">${ls.flatMap(l=>activeSizes().map(i=>({l,i,s:sizes[i]}))).filter(({l,i})=>!state.problems||/넘침|확인|미검수/.test(status(l,i))).map(({l,i,s})=>`<button class="card" data-result="${l}-${i}" style="padding:12px;text-align:left"><div class="mini">${esc(camp().data.short)}<b>${esc(camp().data.amount)}원</b></div><h3 style="margin-top:12px">${langs[l]} · ${s.name}</h3><small>${s.w}×${s.h}</small><div style="margin-top:8px">${badge(status(l,i))}</div></button>`).join('')}</div>`}<div class="callout warn sectionspace">! 글자 넘침은 최소 글자 크기 24px에서 멈춰요. 짧은 문구를 입력하거나 디자이너에게 레이아웃 수정을 요청해 주세요.</div></div>`}
function download(){const count=Object.values(state.approved).filter(v=>v===state.version).length;return `<div class="contentwrap"><div class="callout ${count?'':'warn'}" style="margin-bottom:20px">${count?'✓':'!'} 현재 버전 v${state.version} · 승인 ${count}개 / ${totalResults()}개 <span class="grow"></span><small>승인은 해당 버전의 결과물에만 적용돼요.</small></div><div class="reviewgrid"><section class="card"><div class="row between"><h2>검수·승인</h2>${badge(state.requested?'검수 대기':camp().status)}</div><div class="row" style="gap:22px;margin:24px 0">${[['요청자','김민지'],['언어 검수자','Linh Nguyen'],['최종 승인자','박현우']].map(([r,n])=>`<div><small>${r}</small><p style="font-weight:600">${n}</p></div>`).join('')}</div><div class="callout warn">원문·금액·기간을 수정하면 영향받는 결과물의 승인이 해제되고 재검수가 필요해요.</div><div class="sectionline"></div><h3>수정 의견</h3><p style="font-size:13px;margin:12px 0"><b>박현우</b> <small>오늘 10:42</small><br>베트남어 메인 배너의 제목을 짧게 조정해 주세요. 쿠폰번호와 기간은 확인했습니다.</p><textarea id="comment" placeholder="구체적인 수정 의견을 남겨 주세요" aria-label="수정 의견"></textarea><div class="row" style="margin-top:12px;justify-content:flex-end"><button id="addComment">의견 남기기</button><button id="reject">수정 요청</button><button class="primary" id="approveFinal">선택 결과물 승인</button></div><small>선택: ${langs[state.lang]} · ${sizes[state.size].name} · v${state.version} (역할 전환으로 승인 체험)</small><div class="sectionline"></div><h3>변경 이력</h3><div class="timeline">${state.history.map(h=>`<p>${esc(h)}<small>방금 · 데모 세션</small></p>`).join('')}<p><b>v3</b> 한국어·영어·중국어·일본어 16개 승인<small>오늘 10:20 · 박현우 · 데모</small></p><p><b>v2</b> 할인 금액과 기간 업데이트<small>어제 16:35 · 김민지</small></p><p><b>v1</b> 버스 할인 쿠폰 템플릿 v2.1로 생성<small>어제 14:10 · 김민지</small></p></div></section><section class="card"><h2>다운로드 설정</h2><small>승인된 결과물만 최종본으로 내보낼 수 있어요.</small><label class="field" style="margin-top:23px">다운로드 범위<select id="output"><option value="current" ${state.output==='current'?'selected':''}>현재 결과물 1개</option><option value="selected" ${state.output==='selected'?'selected':''}>선택한 언어·규격</option><option value="approved" ${state.output==='approved'?'selected':''}>승인된 전체 결과물 ZIP (${count}개)</option><option value="proof" ${state.output==='proof'?'selected':''}>현재 결과물 · 검토용 (워터마크)</option></select></label>${state.output==='selected'?`<div class="chips">${activeLangs().flatMap(l=>activeSizes().map(i=>({l,i}))).map(({l,i})=>`<label><input type="checkbox" data-dlselect="${l}-${i}" ${state.selection.includes(l+'-'+i)?'checked':''}> ${langs[l]} · ${sizes[i].name}</label>`).join('')}</div>`:''}<div class="grid2"><label class="field">파일 형식<select id="format"><option ${state.format==='PNG'?'selected':''}>PNG</option><option ${state.format==='JPEG'?'selected':''}>JPEG</option></select></label><label class="field">투명 영역 배경<input type="color" id="exportBg" value="${state.bg}"></label></div>${state.format==='JPEG'?`<label class="field">JPEG 품질 · ${state.quality}%<input type="range" id="quality" min="50" max="100" value="${state.quality}"></label>`:'<small>PNG 원본의 투명 영역은 유지하거나 지정한 배경색으로 채울 수 있어요.</small>'}<div class="sectionline"></div><div class="row between"><span>현재 결과물 크기</span><b>${sizes[state.size].w} × ${sizes[state.size].h} px</b></div><p class="footnote">${sizes[state.size].example?'예시 규격 · 운영 적용 전 설정에서 확인해 주세요.':'등록 규격 · 콘텐츠 이미지'}</p><h3 style="margin:22px 0 10px">파일명 미리보기</h3><div class="filename">${esc(camp().name.replaceAll(' ','_'))}_${codes[state.lang]}_${sizes[state.size].w}x${sizes[state.size].h}_v${state.version}${state.output==='proof'?'_검토용':''}.${state.format.toLowerCase()}</div><button class="primary" id="prepareDownload" style="width:100%;margin-top:25px">↓ ${state.output==='proof'?'검토용':'승인본'} 다운로드 준비</button><div id="downloadState" class="callout sectionspace">${{idle:'데모 · 실제 파일 생성 및 ZIP 다운로드는 연결되지 않았어요.',preparing:'◌ 데모 시뮬레이션 · 다운로드 준비 중…',done:'✓ 설정 확인 완료 · 데모 시뮬레이션입니다. 파일은 생성되지 않았어요.',failed:'! 일부 실패 (데모) · 2개 결과물 준비 실패. 실제 파일은 생성되지 않았어요.'}[state.download]}</div><div class="row" style="margin-top:12px"><button class="small" id="simulateFailure">일부 실패 상태 체험</button>${state.download==='failed'?'<button class="small" id="retryDownload">실패 항목 재시도</button>':''}</div></section></div></div>`}
function settings(){return `<div class="contentwrap"><div class="pagetitle"><div><h1>브랜드·규격 설정</h1><p>출력 용도와 픽셀 크기를 독립적으로 관리해요.</p></div><select id="brand"><option ${state.brand==='Hanpass'?'selected':''}>Hanpass</option><option ${state.brand==='GoHanpass'?'selected':''}>GoHanpass</option></select></div><div class="tabs">${['규격','브랜드','운영 언어'].map(t=>`<button data-settingtab="${t}" class="${state.settingsTab===t?'active':''}">${t}</button>`).join('')}</div>${state.settingsTab==='규격'?`<div class="tablewrap sectionspace"><table><thead><tr>${['용도명','가로 × 세로','안전 여백','허용 형식','최대 용량',''].map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${sizes.map(s=>`<tr><td>${s.name}</td><td>${s.w} × ${s.h} ${s.example?'<span class="badge">예시 규격</span>':''}</td><td>${s.margin||40}px</td><td>${s.formats||'PNG / JPEG'}</td><td>${s.max||5}MB</td><td>등록됨</td></tr>`).join('')}</tbody></table></div><div class="card sectionspace"><h2>새 규격 등록</h2><div class="grid2 sectionspace"><label class="field">용도명<input id="specName" placeholder="예: 팝업 배너 B"></label><div class="split"><label class="field">가로 (px)<input id="specW" type="number" min="1" value="1200"></label><label class="field">세로 (px)<input id="specH" type="number" min="1" value="800"></label></div><label class="field">안전 여백 (px)<input id="specMargin" type="number" min="0" value="40"></label><div class="split"><label class="field">형식<select id="specFormats"><option>PNG / JPEG</option><option>PNG</option><option>JPEG</option></select></label><label class="field">최대 용량 (MB)<input id="specMax" type="number" min="1" value="5"></label></div></div><button class="primary" id="saveSpec">규격 등록</button></div>`:state.settingsTab==='브랜드'?`<div class="card sectionspace"><h2>${state.brand} 브랜드 스타일</h2><div class="assetpreview sectionspace">${state.brand}</div><div class="grid2 sectionspace"><label class="field">브랜드 포인트 색상<input type="color" id="brandColor" value="#2864ee"></label><label class="field">기본 글꼴<select><option>Pretendard</option><option>Noto Sans KR</option></select></label></div><p class="muted">로고 비율과 필수 안내 영역은 잠금으로 보호됩니다.</p><button id="saveBrand" class="primary sectionspace">브랜드 스타일 저장</button></div>`:`<div class="card sectionspace"><h2>운영 언어 · 샘플</h2><div class="chips">${langs.map((l,i)=>`<label>${l} <button class="small ghost" data-removeLang="${i}" aria-label="${l} 비활성화">×</button></label>`).join('')}</div><div class="row"><input id="newLanguage" placeholder="언어명" aria-label="새 언어"><button id="addLanguage">언어 등록</button></div><p class="footnote">이 프로토타입은 12개 샘플 언어를 사용합니다. 기존 캠페인의 결과물은 보존됩니다.</p></div>`}</div>`}
function assets(){return `<div class="contentwrap"><div class="pagetitle"><div><h1>에셋 라이브러리</h1><p>승인된 브랜드 에셋을 찾아 캠페인에 적용하세요.</p></div><label class="field" style="margin:0"><input type="file" id="uploadAsset" accept="image/*" style="width:230px" aria-label="이미지 업로드"></label></div><div class="filters"><input id="assetSearch" placeholder="브랜드·캠페인 검색" value="${esc(state.searchAsset)}"><select id="assetBrand"><option>Hanpass</option><option>GoHanpass</option></select></div><div class="chips">${['전체','로고','상품 사진','버스 이미지','쿠폰 배경','아이콘','일러스트'].map(c=>`<button class="small ${state.assetCategory===c?'active':''}" data-assetcat="${c}">${c}</button>`).join('')}</div><div class="assets">${['로고','상품 사진','버스 이미지','쿠폰 배경','아이콘','일러스트'].filter(c=>(state.assetCategory==='전체'||state.assetCategory===c)&&('Hanpass 버스 할인 쿠폰 '+c).includes(state.searchAsset)).map((c,i)=>`<button class="card" data-asset="${c}" style="padding:13px;text-align:left"><div class="assetpreview">${c==='로고'?'hanpass':c==='쿠폰 배경'?'5,000':c==='아이콘'?'↗':c==='버스 이미지'?'BUS':'에셋'}</div><h3 style="margin-top:10px">${c==='로고'?state.brand:c}</h3><small>Hanpass · ${c==='로고'?'승인됨':'데모 분류 · 이미지 등록 가능'}</small></button>`).join('')}</div><p class="footnote">업로드한 이미지는 이 브라우저의 현재 데모 세션에서만 사용됩니다. 외부 서버에 전송하지 않아요.</p></div>`}
function templates(){return `<div class="contentwrap"><div class="pagetitle"><div><h1>템플릿</h1><p>승인된 레이아웃으로 브랜드 일관성을 지켜요.</p></div><button id="newTemplate" class="primary">＋ 새 버전 만들기</button></div><div class="sectionspace">${templateCards()}</div><div class="card sectionspace"><h2>${tnames[state.template]} · v2.1</h2><div class="grid2 sectionspace"><div><h3>직원 편집 가능</h3><div class="chips">${['제목','설명','금액','쿠폰번호','기간','이미지'].map(n=>`<label><input type="checkbox" checked data-permission> ${n}</label>`).join('')}</div></div><div><h3>잠긴 요소</h3><p class="muted" style="margin-top:12px">🔒 로고 비율 · 필수 안내 · 기본 브랜드 스타일</p></div></div><div class="callout">현재 캠페인은 v2.1에 연결되어 있어요. 새 버전 v2.2를 만들어도 기존 승인 결과물은 바뀌지 않아요.</div><button class="sectionspace" id="useTemplate">이 템플릿으로 캠페인 만들기</button></div></div>`}
